from tasks_api.service import TaskNotFoundError, TaskService


@pytest.fixture()
def repo():
    mock = Mock(spec=TaskRepository)
    mock.next_id.return_value = 1
    return mock


@pytest.fixture()
def now():
    return datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)


@pytest.fixture()
def svc(repo, now):
    return TaskService(repo, now=lambda: now, max_title_length=50)


class TestCreate:
    def test_happy_path(self, svc, repo, now):
        task = svc.create("Buy milk")
        repo.add.assert_called_once()
        assert task.title == "Buy milk"
        assert task.status == TaskStatus.PENDING
        assert task.created_at == now
        assert task.id == 1

    def test_strips_title(self, svc, repo):
        task = svc.create("  spaced  ")
        assert task.title == "spaced"

    def test_rejects_empty_title(self, svc):
        with pytest.raises(ValueError, match="must not be empty"):
            svc.create("   ")

    def test_rejects_non_string_title(self, svc):
        with pytest.raises(ValueError, match="must be a string"):
            svc.create(123)  # type: ignore[arg-type]

    def test_rejects_too_long_title(self, svc):
        with pytest.raises(ValueError, match="50 characters"):
            svc.create("x" * 51)

    def test_rejects_invalid_priority(self, svc):
        with pytest.raises(ValueError, match="must be a TaskPriority"):
            svc.create("t", priority="high")  # type: ignore[arg-type]

    def test_due_at_timezone_required(self, svc):
        naive = datetime(2025, 12, 1)
        with pytest.raises(ValueError, match="timezone-aware"):
            svc.create("t", due_at=naive)

    def test_due_at_not_datetime(self, svc):
        with pytest.raises(ValueError, match="must be a datetime"):
            svc.create("t", due_at="2025-01-01")  # type: ignore[arg-type]

    def test_tags_normalized_and_deduped(self, svc, repo):
        task = svc.create("t", tags=["Work", "work", "  WORK  "])
        assert len(task.tags) == 1
        assert task.tags[0].name == "work"

    def test_with_priority_and_due(self, svc, repo, now):
        due = now + timedelta(days=7)
        task = svc.create("t", priority=TaskPriority.HIGH, due_at=due)
        assert task.priority == TaskPriority.HIGH
        assert task.due_at == due


class TestGet:
    def test_found(self, svc, repo, now):
        task = Task(id=1, title="t", created_at=now)
        repo.get.return_value = task
        assert svc.get(1) is task

    def test_not_found(self, svc, repo):
        repo.get.return_value = None
        with pytest.raises(TaskNotFoundError):
            svc.get(99)


class TestComplete:
    def test_completes(self, svc, repo, now):
        task = Task(id=1, title="t", created_at=now)
        repo.get.return_value = task
        result = svc.complete(1)
        assert result.status == TaskStatus.DONE
        assert result.completed_at == now
        repo.update.assert_called_once()

    def test_already_done(self, svc, repo, now):
        task = Task(id=1, title="t", status=TaskStatus.DONE, created_at=now)
        repo.get.return_value = task
        with pytest.raises(ValueError, match="already done"):
            svc.complete(1)


class TestReopen:
