    def test_sets(self, svc, repo, now):
        task = Task(id=1, title="t", created_at=now)
        repo.get.return_value = task
        due = now + timedelta(days=3)
        result = svc.set_due_at(1, due)
        assert result.due_at == due

    def test_clears(self, svc, repo, now):
        task = Task(id=1, title="t", due_at=now, created_at=now)
        repo.get.return_value = task
        result = svc.set_due_at(1, None)
        assert result.due_at is None


class TestTags:
    def test_add_tags(self, svc, repo, now):
        task = Task(id=1, title="t", tags=[Tag("existing")], created_at=now)
        repo.get.return_value = task
        result = svc.add_tags(1, ["new"])
        assert {t.name for t in result.tags} == {"existing", "new"}

    def test_add_duplicate_tags(self, svc, repo, now):
        task = Task(id=1, title="t", tags=[Tag("work")], created_at=now)
        repo.get.return_value = task
        result = svc.add_tags(1, ["Work"])
        assert len(result.tags) == 1

    def test_remove_tag(self, svc, repo, now):
        task = Task(id=1, title="t", tags=[Tag("work"), Tag("urgent")], created_at=now)
        repo.get.return_value = task
        result = svc.remove_tag(1, "work")
        assert [t.name for t in result.tags] == ["urgent"]

    def test_remove_nonexistent_tag(self, svc, repo, now):
        task = Task(id=1, title="t", tags=[], created_at=now)
        repo.get.return_value = task
        with pytest.raises(ValueError, match="not attached"):
            svc.remove_tag(1, "nope")


class TestServiceInit:
    def test_max_title_length_positive(self):
        with pytest.raises(ValueError, match="must be positive"):
            TaskService(Mock(spec=TaskRepository), max_title_length=0)

